# รายชื่อ IP ที่ถูกแบน — fail2ban jail tpix-rpc เติมบรรทัดลงไฟล์นี้
# ติดตั้งที่ /etc/nginx/conf.d/tpix-banned.map
#
# ⚠️ ไฟล์นี้ต้องมีอยู่จริงเสมอ แม้จะว่างเปล่า
#    nginx-http-tpix.conf include ไฟล์นี้ใน geo block — ถ้าไม่มี nginx จะไม่สตาร์ท
#    (nginx -t จะบอกว่า "open() ... failed" ซึ่งอ่านแล้วอาจไม่นึกถึงจุดนี้)
#
# รูปแบบแต่ละบรรทัด:
#   1.2.3.4 1;
#   5.6.7.0/24 1;
#
# ใส่มือได้เลยถ้าต้องการแบนถาวร แล้ว nginx -t && systemctl reload nginx
